yakit.AutoInitYakit()

# Input your code!

info = `存储桶PUT文件上传漏洞通常是由于存储桶的权限配置不当导致的。当存储桶的权限设置为公共可写（Public Write）时，攻击者可以通过HTTP PUT方法向存储桶中上传任意文件。`

solution = `1.将存储桶权限设置为私有（Private），仅允许授权用户访问。
2.禁止公共写权限，仅在必要时允许公共读权限`

def Check(addr,path) {
    filename=str.RandStr(5)
    txt=str.RandStr(50)
    packet1 = f`PUT /${path}${filename}.txt HTTP/1.1
Host: ${addr}
Content-Type: text/plain

${txt}
`
    packet2=f`GET /${path}${filename}.txt HTTP/1.1
Host: ${addr}
`

    is_https = str.IsTLSServer(addr)
    rsp, req = poc.HTTP(packet1, poc.https(is_https), poc.connectTimeout(5))~
    tmp = poc.ParseBytesToHTTPResponse(rsp)~
    code = tmp.StatusCode

    if code == 200{
        rsp2, req2 = poc.HTTPEx(packet2, poc.https(is_https), poc.connectTimeout(5))~
        if str.Contains(string(rsp2.GetBody()), txt){
            risk.NewRisk(
                string(addr), 
                risk.severity("high"), 
                risk.title(string(addr) + "存在PUT任意文件上传漏洞"), 
                risk.description(info), 
                risk.solution(solution), 
                risk.request(string(req)), 
                risk.response(string(rsp)), 
                risk.type("file-write"),
                risk.details(string(rsp2.Url)) 
            )
        }
    }

}

target = cli.Text("target", cli.setHelp("填写url或host,一行一个"), cli.setRequired(true))
cli.check()
targets = str.ParseStringToLines(target)
wg := sync.NewSizedWaitGroup(50)//线程
yakit.Info(f"len:${len(targets)}")
for target in targets {
    if !str.StringContainsAnyOfSubString(target, ["http://","https://"]){
        target="http://"+target
    }
    ins=str.ParseStringUrlToUrlInstance(target)~
    yakit.Info(ins.Host)
    yakit.Info(ins.Path)
    //yakit.Info(f"正在测试 ${target}")
    // ip, port, _ = str.ParseStringToHostPort(target)
    // addr = str.HostPort(ip, port)
    // if port==0{
    //     addr=ip
    // }
    wg.Add(1)
    go func() {
        defer wg.Done()
        Check(ins.Host,ins.Path)
    }()
}
wg.Wait()
